import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 일괄 변경할 수 있는 항목은 employee 테이블의 아래 항목으로 한정한다.
const FIELDS = ['departmentId', 'email', 'mobilePhone', 'employmentStatus', 'hireDate'];

// 가정: 퇴직 상태의 임직원은 변경 불가 대상으로 보고 제외한다.
const LOCKED_STATUS = '퇴직';

const UPDATE_SQL: Record<string, string> = {
  departmentId: 'UPDATE employee SET department_id = CAST(:value AS bigint), updated_at = now() WHERE employee_id = CAST(:id AS bigint)',
  email: 'UPDATE employee SET email = :value, updated_at = now() WHERE employee_id = CAST(:id AS bigint)',
  mobilePhone: 'UPDATE employee SET mobile_phone = :value, updated_at = now() WHERE employee_id = CAST(:id AS bigint)',
  hireDate: 'UPDATE employee SET hire_date = CAST(:value AS date), updated_at = now() WHERE employee_id = CAST(:id AS bigint)',
  employmentStatus: 'UPDATE employee SET employment_status = :value, updated_at = now() WHERE employee_id = CAST(:id AS bigint)',
  employmentStatusRetire: 'UPDATE employee SET employment_status = :value, retirement_date = CAST(:effectiveDate AS date), updated_at = now() WHERE employee_id = CAST(:id AS bigint)',
};

const DATE_PATTERN = /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/;

@Controller('api/v1')
export class FnSfr01203Controller {
  @Post('/employees/bulk-update')
  @HttpCode(200)
  async bulkUpdateEmployees(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const data = checks.inputOf(req.body);
    const ids = data['employeeIds'];
    const field = data['changeField'];
    const rawValue = data['changeValue'];
    const rawEffective = data['effectiveDate'];
    const invalid = new ApiError(422, 'BULK_UPDATE_INPUT_INVALID', '대상 임직원과 변경 항목·변경 값을 입력해 주세요.');
    if (!Array.isArray(ids) || ids.length === 0) {
      throw invalid;
    }
    if (typeof field !== 'string' || !FIELDS.includes(field)) {
      throw invalid;
    }
    if (rawValue === undefined || rawValue === null || String(rawValue).trim() === '') {
      throw invalid;
    }
    if (data['confirmed'] !== true) {
      throw new ApiError(409, 'BULK_UPDATE_NOT_CONFIRMED', '대상 건수와 변경 내용을 확인한 뒤 실행해 주세요.');
    }
    const value = String(rawValue).trim();
    let effectiveDate: string | null = null;
    if (rawEffective !== undefined && rawEffective !== null && rawEffective !== '') {
      if (typeof rawEffective !== 'string' || !DATE_PATTERN.test(rawEffective)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '변경 효력 일자는 YYYY-MM-DD 형식이어야 합니다.');
      }
      effectiveDate = rawEffective;
    }
    if (field === 'departmentId' && !/^[0-9]+$/.test(value)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '부서 값이 올바르지 않습니다.');
    }
    if (field === 'hireDate' && !DATE_PATTERN.test(value)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '입사일은 YYYY-MM-DD 형식이어야 합니다.');
    }
    if (field === 'email' && value.length > 200) {
      throw new ApiError(400, 'VALIDATION_FAILED', '이메일은 200자 이하여야 합니다.');
    }
    if (field === 'mobilePhone' && value.length > 20) {
      throw new ApiError(400, 'VALIDATION_FAILED', '휴대전화번호는 20자 이하여야 합니다.');
    }
    if (field === 'employmentStatus' && value !== '재직' && value !== '퇴직') {
      throw new ApiError(400, 'VALIDATION_FAILED', '재직 구분은 재직 또는 퇴직이어야 합니다.');
    }
    if (field === 'employmentStatus' && value === '퇴직' && effectiveDate === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '퇴직으로 변경하려면 변경 효력 일자(퇴직일)가 필요합니다.');
    }
    const sqlKey = field === 'employmentStatus' && value === '퇴직' ? 'employmentStatusRetire' : field;
    const targetIds: string[] = [];
    const failures: { employeeId: string; reason: string }[] = [];
    for (const raw of ids) {
      const text = String(raw).trim();
      if (!/^[0-9]+$/.test(text)) {
        failures.push({ employeeId: text, reason: '임직원 ID 형식이 올바르지 않습니다.' });
      } else if (!targetIds.includes(text)) {
        targetIds.push(text);
      }
    }
    return transaction(async (db) => {
      if (field === 'departmentId') {
        const dept = await db.query(
          'SELECT department_id AS "departmentId" FROM department WHERE department_id = CAST(:value AS bigint)',
          { value },
        );
        if (dept.length === 0) {
          throw new ApiError(400, 'VALIDATION_FAILED', '존재하지 않는 부서입니다.');
        }
      }
      let successCount = 0;
      for (const id of targetIds) {
        const rows = await db.query(
          'SELECT employee_id AS "employeeId", employment_status AS "employmentStatus" FROM employee WHERE employee_id = CAST(:id AS bigint)',
          { id },
        );
        if (rows.length === 0) {
          failures.push({ employeeId: id, reason: '존재하지 않는 임직원입니다.' });
          continue;
        }
        if (rows[0]['employmentStatus'] === LOCKED_STATUS) {
          failures.push({ employeeId: id, reason: '퇴직 처리된 임직원은 변경할 수 없습니다.' });
          continue;
        }
        const changed = await db.execute(UPDATE_SQL[sqlKey], { id, value, effectiveDate });
        if (changed > 0) {
          successCount += 1;
        } else {
          failures.push({ employeeId: id, reason: '변경이 적용되지 않았습니다.' });
        }
      }
      return {
        successCount,
        failureCount: failures.length,
        failures,
      };
    });
  }
}

