import { useState } from 'react';
import {
  Band,
  DataTable,
  DateInput,
  Drawer,
  Field,
  Form,
  LookupSelect,
  NumberInput,
  PageProps,
  RefName,
  Row,
  Select,
  TextInput,
  Tiles,
  Num,
  DateText,
  call,
} from '../kit';

const FIELD_OPTIONS: [string, string][] = [
  ['departmentId', '주부서'],
  ['employmentStatus', '재직 구분'],
  ['email', '이메일'],
  ['mobilePhone', '휴대전화번호'],
  ['hireDate', '입사일'],
];

const FIELD_LABEL: Record<string, string> = {
  departmentId: '주부서',
  employmentStatus: '재직 구분',
  email: '이메일',
  mobilePhone: '휴대전화번호',
  hireDate: '입사일',
};

export default function FnSfr01203Page({ role, notify }: PageProps) {
  const [open, setOpen] = useState(false);
  const [targets, setTargets] = useState<number[]>([]);
  const [picker, setPicker] = useState<number | string>('');
  const [field, setField] = useState('');
  const [value, setValue] = useState<unknown>('');
  const [effectiveDate, setEffectiveDate] = useState('');
  const [confirmed, setConfirmed] = useState('');
  const [history, setHistory] = useState<Row[]>([]);
  const [last, setLast] = useState<Row | undefined>(undefined);

  function start() {
    setTargets([]);
    setPicker('');
    setField('');
    setValue('');
    setEffectiveDate('');
    setConfirmed('');
    setOpen(true);
  }

  function addTarget(v: number | string) {
    setPicker('');
    if (typeof v === 'number' && !targets.includes(v)) {
      setTargets([...targets, v]);
    }
  }

  function valueInput() {
    if (field === 'departmentId') {
      return <LookupSelect table="department" role={role} value={value} onChange={(v) => setValue(v)} placeholder="부서 선택" />;
    }
    if (field === 'employmentStatus') {
      return (
        <Select
          value={value}
          onChange={(v) => setValue(v)}
          options={[['재직', '재직'], ['퇴직', '퇴직']]}
        />
      );
    }
    if (field === 'hireDate') {
      return <DateInput value={value} onChange={(v) => setValue(v)} />;
    }
    return <TextInput value={value} onChange={(v) => setValue(v)} />;
  }

  async function submit() {
    if (targets.length === 0) {
      throw new Error('대상 임직원을 선택해 주세요.');
    }
    if (!field) {
      throw new Error('변경 항목을 선택해 주세요.');
    }
    if (value === '' || value === undefined || value === null) {
      throw new Error('변경 값을 입력해 주세요.');
    }
    if (field === 'employmentStatus' && value === '퇴직' && !effectiveDate) {
      throw new Error('퇴직으로 변경하려면 변경 효력 일자(퇴직일)를 입력해 주세요.');
    }
    if (confirmed !== 'Y') {
      throw new Error('대상 건수와 변경 내용을 확인해 주세요.');
    }
    const body: Row = {
      employeeIds: targets,
      changeField: field,
      changeValue: String(value),
      confirmed: true,
    };
    if (effectiveDate) {
      body.effectiveDate = effectiveDate;
    }
    const result = await call('POST', '/employees/bulk-update', role, body);
    const row: Row = {
      id: history.length + 1,
      field,
      value: String(value),
      total: targets.length,
      successCount: result.successCount,
      failureCount: result.failureCount,
      failures: result.failures,
    };
    setLast(row);
    setHistory([row, ...history]);
    setOpen(false);
    notify('인사정보를 일괄 변경했습니다.');
  }

  const failures = ((last?.failures as Row[] | undefined) ?? []);

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>최근 변경 결과</h2>
        <Tiles
          items={[
            ['대상 건수', <Num value={last?.total ?? 0} />],
            ['성공 건수', <Num value={last?.successCount ?? 0} />],
            ['실패 건수', <Num value={last?.failureCount ?? 0} />],
          ]}
        />
      </section>
      <section className="box span-8">
        <h2>일괄 변경 내역</h2>
        <Band total={history.length}>
          <button type="button" onClick={start}>일괄 변경</button>
        </Band>
        <DataTable
          rows={history}
          empty="이 화면에서 처리한 내역이 없습니다."
          onRowClick={(row) => setLast(row)}
          columns={[
            { key: 'field', label: '변경 항목', render: (r) => <>{FIELD_LABEL[String(r.field)] ?? String(r.field)}</> },
            { key: 'value', label: '변경 값' },
            { key: 'total', label: '대상 건수', render: (r) => <Num value={r.total} /> },
            { key: 'successCount', label: '성공 건수', render: (r) => <Num value={r.successCount} /> },
            { key: 'failureCount', label: '실패 건수', render: (r) => <Num value={r.failureCount} /> },
          ]}
        />
      </section>
      <section className="box span-4">
        <h2>실패 사유</h2>
        <DataTable
          rows={failures}
          empty="실패한 대상이 없습니다."
          columns={[
            {
              key: 'employeeId',
              label: '임직원',
              render: (r) => <RefName table="employee" role={role} value={Number(r.employeeId)} />,
            },
            { key: 'reason', label: '사유' },
          ]}
        />
      </section>
      {open && (
        <Drawer title="인사정보 일괄 변경" onClose={() => setOpen(false)}>
          <Form
            submit="일괄 변경 실행"
            onSubmit={submit}
            note={
              <>
                대상 {targets.length}건 · 변경 내용: {FIELD_LABEL[field] ?? '미선택'} → {String(value === '' ? '미입력' : value)}
              </>
            }
          >
            <Field label="변경 대상 임직원" required wide>
              <LookupSelect table="employee" role={role} value={picker} onChange={addTarget} placeholder="임직원을 골라 추가" />
              <ul>
                {targets.map((id) => (
                  <li key={id}>
                    <RefName table="employee" role={role} value={id} />
                    <button type="button" onClick={() => setTargets(targets.filter((t) => t !== id))}>제외</button>
                  </li>
                ))}
              </ul>
            </Field>
            <Field label="일괄 변경할 인사정보 항목" required>
              <Select
                value={field}
                onChange={(v) => {
                  setField(v);
                  setValue('');
                }}
                options={FIELD_OPTIONS}
              />
            </Field>
            <Field label="대상에 일괄 적용할 값" required>
              {valueInput()}
            </Field>
            <Field label="변경 효력 일자" hint="퇴직으로 변경할 때는 퇴직일로 쓰입니다.">
              <DateInput value={effectiveDate} onChange={setEffectiveDate} />
            </Field>
            <Field label="대상 건수와 변경 내용 확인 여부" required>
              <Select
                value={confirmed}
                onChange={setConfirmed}
                options={[['Y', '확인했습니다']]}
                placeholder="확인 필요"
              />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
